#include <set>
#include <functional>

int main() {
    // Historical/Backward Compatible Syntax (Always Safe)
    std::set<int, std::greater<int> > s1;

    // Modern C++11+ Syntax (Generally Accepted)
    std::set<int, std::greater<int>> s2;

    // Example of intentional shift operator (unrelated to templates)
    int x = 10;
    x = x >> 1; // Right shift

    // Note: If C++03 compiler is used, s2 definition fails to compile
    // due to the '>>' being parsed as a single token.
}
